<?php $title='My orders';require 'includes/header.php';if(!logged())redirect('auth/login.php');$s=$pdo->prepare('SELECT * FROM orders WHERE user_id=? ORDER BY created_at DESC');$s->execute([$_SESSION['user']['id']]);$orders=$s->fetchAll(); ?>
<section class="container section"><span class="eyebrow">ORDER CENTER</span><h1>My orders</h1><div class="orders"><?php if($orders): foreach($orders as $o): ?><article class="order"><div><b>#<?=$o['id']?></b><small><?=date('d M Y, h:i A',strtotime($o['created_at']))?></small><p><?=e($o['address'])?></p></div><div class="status <?=strtolower($o['status'])?>"><?=e($o['status'])?></div><strong>₹<?=number_format($o['total'])?></strong></article><?php endforeach; else: ?><div class="empty">No orders yet. <a href="products.php">Shop now</a></div><?php endif; ?></div></section><?php require 'includes/footer.php'; ?>
